  paymentStatus: "unpaid" | "paid" | "failed" | "refunded";
  items: OrderLine[];
  createdAt: string;
  shippingAddress: string;
  providerSessionId?: string;
  stripeSessionId?: string;
};
export type CommerceInvoice = {
